{
  "title": "Is version B ready to launch?",
  "setting": "Day 2 at Harbor Cart",
  "mission": "You are reviewing a test of two checkout buttons. Decide **whether the difference is strong enough to launch B**, and tell the product team what to do next.",
  "deadline": "Product meeting today at 3:00 p.m.",
  "panels": [
    {
      "title": "Checkout button test",
      "metrics": [
        {
          "label": "Visits per version",
          "value": "1,000",
          "note": null
        },
        {
          "label": "A purchases",
          "value": "30",
          "note": "3% of visits"
        },
        {
          "label": "B purchases",
          "value": "40",
          "note": "4% of visits"
        }
      ],
      "note": "Visitors were randomly shown A or B. The test has run for one day."
    }
  ],
  "team": [
    {
      "id": "data",
      "role": "Data analyst",
      "expertise": "Knows how to plan a test and interpret a chance check.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Needs a launch recommendation and wants to avoid delaying checkout improvements.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Calculates rates and checks test results when asked; people make the launch decision.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "evidence",
      "label": "Evidence for a launch decision",
      "start": 20,
      "goodWhen": "high"
    },
    {
      "id": "schedule",
      "label": "Room in the launch schedule",
      "start": 70,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Tell a real difference from chance",
      "practice": "Look at two purchase counts and write one sentence about what the gap does not yet prove."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Write a one-sentence plan stating how many visits each version should get before a decision."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one test result to a teammate in two sentences without using statistics jargon."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "B has 10 more purchases. Can I tell the team we're launching it?"
        },
        {
          "from": "data",
          "text": "That's a promising start, but hypothesis testing asks whether a gap like this could happen by chance even if the buttons work equally well."
        }
      ],
      "prompt": "What do you do before the meeting?",
      "choices": [
        {
          "id": "check-now",
          "text": "Ask {{ai}} to check the gap and estimate how many visits we need.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I'll check the current result and estimate a useful target for both groups."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 15
            },
            {
              "meter": "schedule",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked whether the early gap might be chance instead of treating the larger count as proof.",
              "example": null
            }
          ],
          "next": "checked"
        },
        {
          "id": "request-time",
          "text": "Ask {{product}} to keep the test running before making a launch call.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I can make room, but I need to know what we're waiting for."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 5
            },
            {
              "meter": "schedule",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "More visits can help, but give the team a target before waiting.",
              "example": "\"Let's set a visit target for each version, then review the result.\""
            }
          ],
          "next": "unchecked"
        },
        {
          "id": "send-rates",
          "text": "Send {{product}} the two rates and say B looks promising.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Promising helps, but I still need a clear decision for the meeting."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 0
            },
            {
              "meter": "schedule",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "The rates are accurate, but say what they do and do not support.",
              "example": "\"B is ahead so far, but we haven't checked whether that gap could be chance.\""
            }
          ],
          "next": "unchecked"
        }
      ]
    },
    {
      "id": "unchecked",
      "messages": [
        {
          "from": "product",
          "text": "I need a recommendation today. We can keep the test running, but I'd like a reason and a target."
        }
      ],
      "prompt": "How do you answer?",
      "choices": [
        {
          "id": "get-check",
          "text": "Ask {{ai}} for a chance check and a visit target before deciding.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I'll check both, so the recommendation has a reason and a stopping point."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 15
            },
            {
              "meter": "schedule",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You asked for a visit target instead of waiting without a plan.",
              "example": null
            }
          ],
          "next": "checked"
        },
        {
          "id": "wait-without-target",
          "text": "Keep the test running for five more days, then review the rates.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I'll hold the launch. We should still check the result before calling a winner."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 30
            },
            {
              "meter": "schedule",
              "change": -40
            }
          ],
          "timeJump": {
            "label": "Five days later",
            "panel": {
              "title": "Checkout button test",
              "metrics": [
                {
                  "label": "Visits per version",
                  "value": "6,000",
                  "note": null
                },
                {
                  "label": "A purchases",
                  "value": "180",
                  "note": "3% of visits"
                },
                {
                  "label": "B purchases",
                  "value": "240",
                  "note": "4% of visits"
                }
              ],
              "note": "The test stayed evenly split. No chance check has been run on the new result."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Waiting added observations, but a visit target chosen in advance would make the stopping point clearer.",
              "example": null
            }
          ],
          "next": "final-review"
        },
        {
          "id": "launch-early",
          "text": "Recommend launching B now, based on its 10 extra purchases.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I'll make the switch, but we won't know whether that early gap will hold."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": -10
            },
            {
              "meter": "schedule",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Ten extra purchases in small groups can be chance. Check the gap before making a full launch call.",
              "example": null
            }
          ],
          "next": "early-launch"
        }
      ]
    },
    {
      "id": "checked",
      "messages": [
        {
          "from": "ai",
          "text": "With 1,000 visits each, the 10-purchase gap could easily happen by chance. If the real difference is about 1 percentage point, roughly 6,000 visits per version gives us a good chance of spotting it."
        },
        {
          "from": "data",
          "text": "That's a sample-size estimate, not a promise. Let's decide when to look again before seeing more results."
        }
      ],
      "prompt": "What plan do you bring to {{product}}?",
      "choices": [
        {
          "id": "five-days-only",
          "text": "Run five more days and review whatever rates we have then.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I can wait five days, though I'd rather have a clear visit target."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 25
            },
            {
              "meter": "schedule",
              "change": -40
            }
          ],
          "timeJump": {
            "label": "Five days later",
            "panel": {
              "title": "Checkout button test",
              "metrics": [
                {
                  "label": "Visits per version",
                  "value": "6,000",
                  "note": null
                },
                {
                  "label": "A purchases",
                  "value": "180",
                  "note": "3% of visits"
                },
                {
                  "label": "B purchases",
                  "value": "240",
                  "note": "4% of visits"
                }
              ],
              "note": "The test stayed evenly split. The new result still needs a chance check."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "You allowed more data to arrive, but a visit target is clearer than a calendar date alone.",
              "example": "\"Let's review after each version reaches about 6,000 visits.\""
            }
          ],
          "next": "final-review"
        },
        {
          "id": "set-target",
          "text": "Keep the split even and review at about 6,000 visits per version.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That gives me a reason to hold the launch and a clear point to revisit it."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 35
            },
            {
              "meter": "schedule",
              "change": -40
            }
          ],
          "timeJump": {
            "label": "Five days later",
            "panel": {
              "title": "Checkout button test",
              "metrics": [
                {
                  "label": "Visits per version",
                  "value": "6,000",
                  "note": null
                },
                {
                  "label": "A purchases",
                  "value": "180",
                  "note": "3% of visits"
                },
                {
                  "label": "B purchases",
                  "value": "240",
                  "note": "4% of visits"
                }
              ],
              "note": "Both versions reached the target. The new result still needs a chance check."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You set the review point before seeing more results and kept the groups comparable.",
              "example": null
            }
          ],
          "next": "final-review"
        },
        {
          "id": "provisional-winner",
          "text": "Run five more days, but announce B as the likely winner now.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I'll call that a hunch, not a launch decision. We'll revisit it after five days."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 20
            },
            {
              "meter": "schedule",
              "change": -40
            }
          ],
          "timeJump": {
            "label": "Five days later",
            "panel": {
              "title": "Checkout button test",
              "metrics": [
                {
                  "label": "Visits per version",
                  "value": "6,000",
                  "note": null
                },
                {
                  "label": "A purchases",
                  "value": "180",
                  "note": "3% of visits"
                },
                {
                  "label": "B purchases",
                  "value": "240",
                  "note": "4% of visits"
                }
              ],
              "note": "The test stayed evenly split. The new result still needs a chance check."
            }
          },
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Calling B a winner now can sound firmer than the early evidence supports.",
              "example": "\"B is ahead, but we'll decide after more visits and a fresh check.\""
            }
          ],
          "next": "final-review"
        }
      ]
    },
    {
      "id": "final-review",
      "messages": [
        {
          "from": "data",
          "text": "Each version now has 6,000 visits. A has 180 purchases; B has 240. We need a final recommendation."
        },
        {
          "from": "product",
          "text": "Can I launch B, or should we keep the test running?"
        }
      ],
      "prompt": "What do you send {{product}}?",
      "choices": [
        {
          "id": "wait-again",
          "text": "Keep the test running another week without checking this result.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I can hold the launch, but I need to know what the extra week would answer."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 0
            },
            {
              "meter": "schedule",
              "change": -25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "More data has a cost. Check the result you already have before asking for another delay.",
              "example": null
            }
          ],
          "next": "held"
        },
        {
          "id": "check-and-recommend",
          "text": "Ask {{ai}} to check the new gap, then recommend B in plain words.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "The new gap is unlikely to be just chance. B had 60 more purchases across 6,000 visits per version: 4% versus 3%."
            },
            {
              "from": "product",
              "text": "That's clear. I'll launch B based on your recommendation and record the test result."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 25
            },
            {
              "meter": "schedule",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked the completed test rather than relying only on the early check.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "You gave {{product}} both the plain-language conclusion and the purchase rates behind it.",
              "example": "\"B had more purchases, and the completed test suggests the gap is unlikely to be chance. I recommend B.\""
            }
          ],
          "next": "launched"
        },
        {
          "id": "rates-only",
          "text": "Recommend B using its higher rate, without checking the new gap.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I'll launch B. Please flag that we haven't documented a chance check on the final numbers."
            }
          ],
          "effects": [
            {
              "meter": "evidence",
              "change": 5
            },
            {
              "meter": "schedule",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "The larger trial is encouraging, but check its result before presenting the gap as reliable.",
              "example": null
            }
          ],
          "next": "launched-unchecked"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "early-launch",
      "outcome": "B went live after 40 purchases versus A's 30 in the first 1,000 visits per version. The early gap might have been chance, so the team does not yet know whether it will hold."
    },
    {
      "id": "held",
      "outcome": "The team kept both versions running despite B's 240 purchases versus A's 180 across 6,000 visits each. Launch is delayed, and the completed result still has not been checked."
    },
    {
      "id": "launched",
      "outcome": "B went live after the completed test and chance check: 240 of 6,000 visits led to purchases, versus 180 of 6,000 for A. That is 4% versus 3%, a gap unlikely to be just chance."
    },
    {
      "id": "launched-unchecked",
      "outcome": "B went live on a 4% purchase rate versus A's 3% across 6,000 visits each. The team has the observed gap, but no documented chance check on the final result."
    }
  ],
  "summary": [
    "Hypothesis testing asks whether an observed gap could reasonably happen by chance if there were no real difference.",
    "Choose a review target before seeing more results, and check the result when that target is reached.",
    "A useful recommendation tells teammates what the numbers show, what the chance check says, and what action you recommend."
  ]
}

{
  "title": "Por que a luz azul abre a portinha?",
  "setting": "Tarde no Museu Faísca",
  "mission": "Numa exposição imaginária, uma portinha responde à luz azul, mas não à vermelha. Descubra **o que cada luz consegue fazer** e observe o que acontece quando ela atravessa duas aberturas.",
  "deadline": null,
  "panels": [],
  "team": [
    {
      "id": "mediadora",
      "role": "Mediadora da exposição",
      "expertise": "Conhece o funcionamento da portinha e da tela.",
      "ai": false
    },
    {
      "id": "tecnico",
      "role": "Técnico da exposição",
      "expertise": "Quer abrir a portinha para o próximo grupo.",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "pistas",
      "label": "Pistas reunidas",
      "start": 10,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "pacotes",
      "name": "Energia em pacotes",
      "practice": "Explique em uma frase por que uma luz vermelha mais forte pode continuar sem abrir a portinha."
    },
    {
      "id": "dualidade",
      "name": "Dualidade onda-partícula",
      "practice": "Descreva em duas frases o que aparece primeiro e o que se forma depois na tela."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "mediadora",
          "text": "A portinha precisa receber energia em pacotes mínimos, chamados quanta. Cada pacote de luz azul traz mais energia que um de luz vermelha."
        },
        {
          "from": "tecnico",
          "text": "O próximo grupo já está chegando. Será que aumentar bastante a luz vermelha resolve?"
        }
      ],
      "prompt": "O que você tenta primeiro?",
      "choices": [
        {
          "id": "comparar",
          "text": "Deixar as duas lanternas igualmente fracas e testar cada cor na portinha.",
          "quality": "strong",
          "replies": [
            {
              "from": "tecnico",
              "text": "A azul abriu a portinha; a vermelha, com a mesma força, não abriu."
            },
            {
              "from": "mediadora",
              "text": "Um pacote azul tem energia suficiente para abrir. Os pacotes vermelhos não têm; mandar mais deles não muda a energia de cada um."
            }
          ],
          "effects": [
            {
              "meter": "pistas",
              "change": 35
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "good",
              "text": "Você comparou as cores sem mudar a força da luz. Assim, ficou mais fácil perceber que importa a energia de cada pacote.",
              "example": null
            }
          ],
          "next": "tela"
        },
        {
          "id": "reforcar",
          "text": "Deixar a lanterna vermelha bem forte para tentar abrir a portinha logo.",
          "quality": "weak",
          "replies": [
            {
              "from": "tecnico",
              "text": "Mesmo com a luz vermelha mais forte, a portinha continua fechada."
            }
          ],
          "effects": [
            {
              "meter": "pistas",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "improve",
              "text": "Aumentar a luz vermelha envia mais pacotes, mas não dá mais energia a cada um. Compare as cores com a mesma força para investigar a diferença.",
              "example": null
            }
          ],
          "next": "retomar"
        }
      ]
    },
    {
      "id": "tela",
      "messages": [
        {
          "from": "mediadora",
          "text": "A portinha abriu! Ao lado, a luz azul pode atravessar duas aberturas estreitas até uma tela. Dá para diminuir a luz e acompanhar o que surge ali."
        },
        {
          "from": "tecnico",
          "text": "Também podemos deixar a tela para o próximo grupo e seguir."
        }
      ],
      "prompt": "O que você faz antes de seguir?",
      "choices": [
        {
          "id": "seguir",
          "text": "Seguir adiante, já que a portinha abriu com a luz azul.",
          "quality": "weak",
          "replies": [
            {
              "from": "mediadora",
              "text": "A comparação das cores ficou clara. A tela ainda poderia mostrar outro lado do comportamento da luz."
            }
          ],
          "effects": [
            {
              "meter": "pistas",
              "change": 0
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade",
              "kind": "improve",
              "text": "Você resolveu a questão da portinha, mas deixou uma pista sem olhar. Observe a luz fraca na tela por algum tempo.",
              "example": null
            }
          ],
          "next": "partial"
        },
        {
          "id": "observar",
          "text": "Diminuir a luz azul e observar a tela após as duas aberturas.",
          "quality": "strong",
          "replies": [
            {
              "from": "mediadora",
              "text": "Primeiro aparecem pontos separados na tela. Com o tempo, eles formam faixas claras e escuras, como um desenho feito por ondas. A luz chega em pontos, como partículas, e também se comporta como onda: é a dualidade onda-partícula."
            }
          ],
          "effects": [
            {
              "meter": "pistas",
              "change": 40
            }
          ],
          "timeJump": {
            "label": "Alguns minutos depois",
            "panel": {
              "title": "Tela da exposição",
              "metrics": [
                {
                  "label": "No começo",
                  "value": "Pontos separados",
                  "note": null
                },
                {
                  "label": "Depois",
                  "value": "Faixas na tela",
                  "note": null
                }
              ],
              "note": "A luz azul continuou fraca durante a observação."
            }
          },
          "notes": [
            {
              "skill": "dualidade",
              "kind": "good",
              "text": "Você acompanhou tanto a chegada dos pontos quanto o desenho que surgiu depois, reunindo as duas pistas sobre a luz.",
              "example": null
            }
          ],
          "next": "complete"
        }
      ]
    },
    {
      "id": "retomar",
      "messages": [
        {
          "from": "mediadora",
          "text": "A luz vermelha mais forte não abriu a portinha. Ainda dá tempo de comparar as cores com a mesma força. Depois, podemos olhar a tela com duas aberturas."
        },
        {
          "from": "tecnico",
          "text": "O grupo está chegando, mas consigo esperar mais um pouco."
        }
      ],
      "prompt": "Como você usa esse tempo?",
      "choices": [
        {
          "id": "repetir",
          "text": "Comparar as cores igualmente fracas e depois observar a luz azul na tela.",
          "quality": "strong",
          "replies": [
